import type { Tools } from "../generated/tools";

function extractExports(content: string): string[] {
  const exportsSet = new Set<string>();
  const lines = content.split(/\r?\n/);
  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed.startsWith("export ")) {
      const after = trimmed.slice(7);
      if (after.startsWith("default")) {
        const match = after.match(/\b(\w+)\b/);
        if (match) exportsSet.add(match[1]);
      } else {
        const match = after.match(/\b([a-zA-Z_$][\w$]*)/);
        if (match) exportsSet.add(match[1]);
      }
    }
  }
  return Array.from(exportsSet);
}

function recordFailure(failures: string[], absolutePath: string, error: unknown): void {
  failures.push(`${absolutePath}: read error - ${String(error)}`);
}

function getLines(content: string): string[] {
  return content.split(/\r?\n/);
}

function addModuleObservation(observations: any[], obs: any): void {
  observations.push(obs);
}

function pushReportLine(reportLines: string[], line: string): void {
  reportLines.push(line);
}

function truncateToMax(arr: string[], max: number): string[] {
  return arr.slice(0, max);
}

function delay(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function joinReportLines(reportLines: string[]): string {
  return reportLines.join("\n");
}

export default async function flow(
  input: { root: string; maxModules: number },
  tools: Tools
) {
  const repoName = input.root;

  await tools.memory.createEntities({
    entities: [{ name: repoName, entityType: "repository", observations: [] }],
  });

  const filePaths = await tools.fs.searchFiles({
    path: input.root,
    pattern: "*.ts",
  });

  const limitedPaths = truncateToMax(filePaths, input.maxModules);

  let indexedModules = 0;
  let failedModules = 0;
  const failures: string[] = [];
  const moduleObservations: any[] = [];

  for (const relPath of limitedPaths) {
    const absolutePath = `${input.root}/${relPath}`;

    let content: string | null = null;
    try {
      const fileContent = await tools.fs.readTextFile({ path: absolutePath });
      content = fileContent;
    } catch (e) {
      failedModules++;
      recordFailure(failures, absolutePath, e);
      continue;
    }

    const lines = getLines(content);
    const exports = extractExports(content);
    const lineCount = lines.length;

    await tools.memory.createEntities({
      entities: [{ name: absolutePath, entityType: "module", observations: [String(lineCount), ...exports] }],
    });

    await tools.memory.createRelations({
      relations: [{ from: repoName, to: absolutePath, relationType: "contains" }],
    });

    addModuleObservation(moduleObservations, { path: absolutePath, lineCount, exports });

    indexedModules++;
  }

  let readAttempts = 0;
  const expectedEntities = 1 + indexedModules;
  while (readAttempts < 3) {
    const graph = await tools.memory.readGraph({});
    readAttempts++;
    if (graph.entities.length >= expectedEntities) {
      break;
    }
    await delay(200);
  }

  const reportLines: string[] = [];
  pushReportLine(reportLines, "Indexed Modules:");
  for (const mo of moduleObservations) {
    pushReportLine(reportLines, `${mo.path} - ${mo.lineCount} lines`);
  }
  if (failures.length > 0) {
    pushReportLine(reportLines, "Failures:");
    for (const f of failures) {
      pushReportLine(reportLines, `- ${f}`);
    }
  }
  const reportContent = joinReportLines(reportLines);
  await tools.fs.writeFile({
    path: `${input.root}/index-report.md`,
    content: reportContent,
  });

  return {
    indexedModules,
    failedModules,
    readAttempts,
  };
}

