type Grade = "large" | "documented" | "plain";

function extractPaths(content: string): string[] {
  return content
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.length > 0 && line.endsWith(".ts"));
}

function parseSizeFromInfo(content: string): number {
  try {
    const parsed = JSON.parse(content);
    if (parsed && typeof parsed === "object") {
      if (typeof parsed.size === "number") return parsed.size;
      if (typeof parsed.size === "string") return parseInt(parsed.size, 10) || 0;
    }
  } catch {
    // not JSON — fall through to regex
  }
  const match = content.match(/size[:\s]*(\d+)/i);
  return match ? parseInt(match[1], 10) : 0;
}

function gradeModule(sizeBytes: number, text: string): Grade {
  if (sizeBytes > 200) {
    return "large";
  }
  if (text.includes("/**")) {
    return "documented";
  }
  return "plain";
}

function countByGrade(grades: { path: string; grade: Grade }[]): Record<Grade, number> {
  const counts: Record<Grade, number> = { large: 0, documented: 0, plain: 0 };
  for (const g of grades) {
    counts[g.grade] += 1;
  }
  return counts;
}

function takeFirst<T>(items: T[], max: number): T[] {
  return items.slice(0, max);
}

function recordGrade(grades: { path: string; grade: Grade }[], path: string, grade: Grade): void {
  grades.push({ path, grade });
}

function recordReadFailure(failures: string[], path: string, error: unknown): void {
  failures.push(`${path}: ${String(error)}`);
}

function buildAuditMd(
  grades: { path: string; grade: Grade }[],
  failures: string[],
  thoughtCount: number
): string {
  const lines: string[] = [];
  lines.push("# Repository Audit");
  lines.push("");
  lines.push("## Modules");
  lines.push("");
  for (const g of grades) {
    lines.push(`- \`${g.path}\`: ${g.grade}`);
  }
  if (failures.length > 0) {
    lines.push("");
    lines.push("## Read failures");
    lines.push("");
    for (const f of failures) {
      lines.push(`- ${f}`);
    }
  }
  lines.push("");
  lines.push("## reasoning");
  lines.push("");
  lines.push(`Recorded ${thoughtCount} sequential thoughts (1, 2, 3 of 3).`);
  return lines.join("\n");
}

export default async function flow(
  input: { root: string; maxModules: number },
  tools: Tools
) {
  const [listing, tree, allowed] = await Promise.all([
    tools.fs.listDirectoryWithSizes({ path: input.root }),
    tools.fs.directoryTree({ path: input.root }),
    tools.fs.listAllowedDirectories({})
  ]);

  const searchResult = await tools.fs.searchFiles({ path: input.root, pattern: "*.ts" });
  const allPaths = extractPaths(searchResult.content);
  const pathsToAudit = takeFirst(allPaths, input.maxModules);

  const grades: { path: string; grade: Grade }[] = [];
  const readFailures: string[] = [];

  for (const path of pathsToAudit) {
    try {
      const info = await tools.fs.getFileInfo({ path });
      const sizeBytes = parseSizeFromInfo(info.content);
      const fileContent = await tools.fs.readTextFile({ path });
      const grade = gradeModule(sizeBytes, fileContent.content);
      recordGrade(grades, path, grade);
    } catch (error) {
      recordReadFailure(readFailures, path, error);
    }
  }

  const counts = countByGrade(grades);

  const thought1 = await tools.reasoning.sequentialThinking({
    thought: `Repository audit of ${input.root}. Gathered directory listing (${listing.content.length} chars), recursive tree (${tree.content.length} chars), and allowed directories (${allowed.content}). Found ${allPaths.length} TypeScript files; auditing ${pathsToAudit.length}. Initial grade distribution: large=${counts.large}, documented=${counts.documented}, plain=${counts.plain}.`,
    nextThoughtNeeded: true,
    thoughtNumber: 1,
    totalThoughts: 3
  });

  const thought2 = await tools.reasoning.sequentialThinking({
    thought: `Module-by-module breakdown: ${grades.map((g) => `${g.path}=${g.grade}`).join(", ")}. Read failures: ${readFailures.length}. Evaluating whether documentation coverage and file sizes are acceptable for release.`,
    nextThoughtNeeded: true,
    thoughtNumber: 2,
    totalThoughts: 3
  });

  const thought3 = await tools.reasoning.sequentialThinking({
    thought: `Audit complete. Writing audit.md with ${grades.length} module grades and a reasoning section. Returning grade counts (large=${counts.large}, documented=${counts.documented}, plain=${counts.plain}) and thought count (3).`,
    nextThoughtNeeded: false,
    thoughtNumber: 3,
    totalThoughts: 3
  });

  const auditContent = buildAuditMd(grades, readFailures, 3);
  await tools.fs.writeFile({ path: `${input.root}/audit.md`, content: auditContent });

  return {
    grades: counts,
    thoughtsRecorded: 3,
    failures: readFailures
  };
}

