function getMdFilesFromTree(treeContent: string, root: string): string[] {
  try {
    const obj = JSON.parse(treeContent);
    const result: string[] = [];
    function walk(node: any, relativePath: string) {
      if (node.type === "file") {
        if (node.name.endsWith(".md")) {
          result.push(relativePath);
        }
      } else if (node.type === "directory") {
        for (const child of node.children ?? []) {
          walk(child, relativePath ? `${relativePath}/${child.name}` : child.name);
        }
      }
    }
    walk(obj, "");
    return result.map(p => (p.startsWith("/") ? p : `${root}/${p}`));
  } catch {
    return [];
  }
}

function parseReadMultipleFiles(content: string): { path: string; content: string }[] {
  try {
    const parsed = JSON.parse(content);
    if (Array.isArray(parsed)) {
      const out: { path: string; content: string }[] = [];
      for (const item of parsed) {
        if (typeof item === "object" && item !== null && typeof item.path === "string" && typeof item.content === "string") {
          out.push({ path: item.path, content: item.content });
        }
      }
      return out;
    }
  } catch {
    const lines = content.split("\n");
    const result: { path: string; content: string }[] = [];
    let currentPath: string | null = null;
    let currentContent: string[] = [];
    for (const line of lines) {
      if (line.startsWith("=== ") && line.endsWith(" ===")) {
        if (currentPath !== null) {
          result.push({ path: currentPath, content: currentContent.join("\n") });
        }
        currentPath = line.slice(4, -4);
        currentContent = [];
      } else {
        if (currentPath !== null) {
          currentContent.push(line);
        }
      }
    }
    if (currentPath !== null) {
      result.push({ path: currentPath, content: currentContent.join("\n") });
    }
    return result;
  }
  return [];
}

