              observations: [`Archived at: ${archivePath}`]
            }
          ]
        });
      } catch (error) {
        recordFailure(failures, originalPath, error);
        continue;
      }

      migrated += 1;
    }
  }

  const reportContent = buildReport(migrated, skipped, failures, abandoned);

  await tools.fs.writeFile({
    path: `${input.root}/migration-report.md`,
    content: reportContent
  });

  return { migrated, skipped, failed: failures.length, abandoned };
}

import type { Tools } from "../generated/tools";

type Location = "New York" | "Chicago" | "Los Angeles";

const locations: Location[] = ["New York", "Chicago", "Los Angeles"];

type CycleRecord = {
  attempt: number;
  location: string;
  temperature: number | null;
  conditions: string | null;
  error: string | null;
};

function recordSuccess(
  records: CycleRecord[],
  attempt: number,
  location: string,
  temperature: number,
  conditions: string,
): void {
  records.push({ attempt, location, temperature, conditions, error: null });
}

function recordFailure(
  records: CycleRecord[],
  attempt: number,
  location: string,
  error: unknown,
): void {
  records.push({
    attempt,
    location,
    temperature: null,
    conditions: null,
    error: String(error),
  });
}

function buildDigest(
  records: CycleRecord[],
  total: number,
  successes: number,
  failures: number,
  average: number,
): string {
  const lines = records.map((r) => {
    if (r.error !== null) {
      return `Cycle ${r.attempt} | ${r.location} | failed | ${r.error}`;
    }
    return `Cycle ${r.attempt} | ${r.location} | ${r.temperature} | ${r.conditions}`;
  });
  return `# Status Digest\n\n${lines.join("\n")}\n\nTotals: polled=${total}, successful=${successes}, failed=${failures}, average temperature=${average}\n`;
}

export default async function flow(
  input: { root: string; maxCycles: number },
  tools: Tools,
) {
  if (input.maxCycles < 1) {
    return { cycles: 0 };
  }

  let attempt = 0;
  let successes = 0;
  let failures = 0;
  let totalTemp = 0;
  const records: CycleRecord[] = [];

  while (attempt < input.maxCycles) {
    attempt += 1;
    const location = locations[(attempt - 1) % locations.length];

    await tools.everything.echo({
      message: `Cycle ${attempt} of ${input.maxCycles}: polling ${location}`,
    });

    try {
      const payload = await tools.everything.getStructuredContent({ location });
      totalTemp += payload.temperature;
      successes += 1;
      recordSuccess(records, attempt, location, payload.temperature, payload.conditions);
    } catch (error) {
      failures += 1;
      recordFailure(records, attempt, location, error);
    }
  }

  const sum = await tools.everything.getSum({ a: successes, b: failures });
  const total = sum as number;
  const average = successes > 0 ? totalTemp / successes : 0;
  const digest = buildDigest(records, total, successes, failures, average);

  await tools.fs.writeFile({ path: `${input.root}/digest.md`, content: digest });

  return { cycles: attempt, failed: failures, average };
}

import type { Tools } from "../generated/tools";

function splitLines(content: string): string[] {
  return content.split('\n');
}

function extractDropFiles(lines: string[]): string[] {
  return lines
    .filter((line) => line.startsWith('[FILE] '))
    .map((line) => line.slice(7).trim())
    .filter((name) => /^drop-.*\.csv$/.test(name));
}

function formatRegionTotals(totals: Record<string, number>): string[] {
  return Object.entries(totals).map(([region, total]) => `${region}: ${total.toFixed(2)}`);
}

function formatRejects(rejects: { id: string; reason: string }[]): string[] {
  return rejects.map(r => `${r.id}: ${r.reason}`);
}

function getLine(rows: string[], i: number): string {
  return rows[i].trim();
}

export default async function flow(
  input: { root: string; maxRows: number },
  tools: Tools
) {
  // 1. List directory and extract drop-*.csv filenames
  const listResult = await tools.fs.listDirectory({ path: input.root });
  const lines = splitLines(listResult.content);
  const fileNames = extractDropFiles(lines);

  if (fileNames.length === 0) {
    return { folded: 0, reason: "no-drops" };
  }

  // Counters
  let foldedCount = 0;
  let rejectedCount = 0;
  let missingRegions = 0;

  // Attempt to read drop-north.csv (missing region is counted on failure)
  try {
    await tools.fs.readTextFile({ path: `${input.root}/drop-north.csv` });
  } catch {
    missingRegions += 1;
  }

  // Aggregation structures
  const regionTotals: Record<string, number> = {};
  const rejects: { id: string; reason: string }[] = [];

  // Process each drop file
  outer: for (const file of fileNames) {
    const filePath = `${input.root}/${file}`;
    const fileData = await tools.fs.readTextFile({ path: filePath });
    const rows = splitLines(fileData.content);

    for (let i = 1; i < rows.length; i++) {
      const line = getLine(rows, i);
      if (!line) continue;

      const parts = line.split(',');
      const id = parts[0];
      const region = parts[1];
      const amountStr = parts[2];

      if (!region) {
        rejects.push({ id, reason: "empty region" });
        rejectedCount++;
        continue;
      }

      const amount = parseFloat(amountStr);
      if (isNaN(amount)) {
        rejects.push({ id, reason: "invalid amount" });
        rejectedCount++;
        continue;
      }

      // Valid row
      regionTotals[region] = (regionTotals[region] || 0) + amount;
      foldedCount++;

      if (foldedCount >= input.maxRows) {
        break outer;
      }
    }
  }

  // Write ledger.md
  const ledgerLines = formatRegionTotals(regionTotals);
  await tools.fs.writeFile({
    path: `${input.root}/ledger.md`,
    content: ledgerLines.join('\n')
  });

  // Write rejects.md
  const rejectsLines = formatRejects(rejects);
  await tools.fs.writeFile({
    path: `${input.root}/rejects.md`,
    content: rejectsLines.join('\n')
  });

  return { folded: foldedCount, rejected: rejectedCount, missingRegions };
}
